INSERT INTO permissions(key,description) VALUES ('company_settings.manage','Manage authenticated tenant company settings'),('development.create','Create Developments for the authenticated tenant') ON CONFLICT(key) DO UPDATE SET description=EXCLUDED.description;
WITH grants(role_key,permission_key) AS (VALUES ('admin','company_settings.manage'),('commercial_director','company_settings.manage'),('admin','development.create'),('commercial_director','development.create'),('commercial_manager','development.create')) INSERT INTO role_permissions(role_id,permission_key) SELECT r.id,g.permission_key FROM grants g JOIN roles r ON r.key=g.role_key ON CONFLICT DO NOTHING;
CREATE TABLE tenant_company_settings(client_id UUID PRIMARY KEY REFERENCES clients(id) ON DELETE CASCADE,settings JSONB NOT NULL DEFAULT '{}'::jsonb,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),updated_by_user_id UUID REFERENCES buildlite_users(id) ON DELETE RESTRICT,updated_by_membership_id UUID REFERENCES client_user_memberships(id) ON DELETE RESTRICT,updated_by_provider_user_id TEXT,updated_by_display_name TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE tenant_provisioning_audit(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key TEXT NOT NULL UNIQUE,client_id UUID NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,initial_user_id UUID NOT NULL REFERENCES buildlite_users(id) ON DELETE RESTRICT,initial_membership_id UUID NOT NULL REFERENCES client_user_memberships(id) ON DELETE RESTRICT,initial_role_key TEXT NOT NULL,tenant_code TEXT NOT NULL,tenant_name TEXT NOT NULL,actor_user_id UUID NOT NULL REFERENCES buildlite_users(id) ON DELETE RESTRICT,actor_provider_user_id TEXT NOT NULL,actor_display_name TEXT NOT NULL,authority TEXT NOT NULL CHECK(authority='platform.tenant_provision'),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION protect_tenant_provisioning_audit() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'Tenant provisioning audit is append-only'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_tenant_provisioning_audit_immutable BEFORE UPDATE OR DELETE ON tenant_provisioning_audit FOR EACH ROW EXECUTE FUNCTION protect_tenant_provisioning_audit();
